function crewsForDepartment(dept) {
	var results = [];
	if(dept) {
		var dc = dept.getCode();
		var crews = gks.clark.inspections.model.Crew.all();
		for(var i=0;i<crews.length;++i) {
			if(crews[i].getDepartment() == dc) {
				results.push(crews[i]);
			}
		}
	}
	return results;
}
